INSERT INTO cakes (name, slug, description, price_cents, currency, category_id, image_url, image_key, is_featured, is_available, display_order) VALUES ('Tuxedo Birthday Cake', 'tuxedo-birthday-cake', 'A dapper black tuxedo cake with a white fondant shirt collar, gold bow tie and buttons, gold sphere accents and a personalised glitter topper. A stylish centrepiece for his birthday.', 0, 'USD', 1, '/media/images/cakes/tuxedo-birthday-cake-01.jpg', 'images/cakes/tuxedo-birthday-cake-01.jpg', 1, 1, 0);
