INSERT INTO cakes (name, slug, description, price_cents, currency, category_id, image_url, image_key, is_featured, is_available, display_order) VALUES ('Royal Crown First Birthday Cake', 'royal-crown-first-birthday-cake', 'A two-tier first birthday cake in starry night-sky blue, finished with a gold crown, a gold number one, pearl borders and a personalised name. Fit for a little prince.', 0, 'USD', 1, '/media/images/cakes/royal-crown-first-birthday-cake-01.jpg', 'images/cakes/royal-crown-first-birthday-cake-01.jpg', 1, 1, 0);
