INSERT INTO cakes (name, slug, description, price_cents, currency, category_id, image_url, image_key, is_featured, is_available, display_order) VALUES ('Navy & Gold Doctoral Graduation Cake', 'navy-and-gold-doctoral-graduation-cake', 'A two-tier graduation cake in navy and white with gold leaf accents, sugar roses, a fondant cap and diploma, and a personalised "Class of" message, made to celebrate a doctoral graduate.', 0, 'USD', 1, '/media/images/cakes/navy-and-gold-doctoral-graduation-cake-01.jpg', 'images/cakes/navy-and-gold-doctoral-graduation-cake-01.jpg', 1, 1, 0);
