INSERT INTO cakes (name, slug, description, price_cents, currency, category_id, image_url, image_key, is_featured, is_available, display_order) VALUES ('Blue & Pink Number 3 Drip Cake', 'blue-and-pink-number-3-drip-cake', 'A sky-blue birthday cake with a hot-pink drip, a fondant bow, snowflake accents, pastel spheres and a big number 3, personalised with the birthday child''s name. Matching cupcakes available.', 0, 'USD', 1, '/media/images/cakes/blue-and-pink-number-3-drip-cake-01.jpg', 'images/cakes/blue-and-pink-number-3-drip-cake-01.jpg', 1, 1, 0);
